// C7F7E627 offset of last shader
// 02AEC960 is offset of first shader
// shader count is 0x0315F6

// 0xec
struct T3FXPackHeader
{
    uint32_t magic;
    uint32_t version;
    uint32_t programCount;
    uint32_t shaderCount;
    uint32_t shaderDataOffset;
};

struct T3EffectCachePackageShader
{
    uint32_t shaderType;
    uint32_t neededParameters[5]; // BitSet<enum_T3EffectParameterType,150,0>
    uint32_t offset;
    uint32_t size;
};

struct T3EffectCachePackageProgram
{
    uint32_t effectType;        // index in T3EffectDesc static array
    uint32_t effectFeatures[3]; // BitSet<enum_T3EffectFeature,84,0>
    uint64_t materialCrc;
    uint32_t effectQuality;
    uint32_t passCount;
    uint32_t samplerCount;
};

struct T3EffectCacheProgram
{
    struct T3EffectCachePackageProgram package;
    struct T3EffectCacheSampler
    {
        uint32_t mSamplerParameterIndex;
        uint32_t mSamplerState;
        uint32_t mSamplerStateMask;
    } *samplers;
    union
    {
        struct T3EffectCachePassDraw
        {
            uint32_t mRenderStateBlock[3];
            uint32_t mRenderStateMask[3];
            uint32_t t3EffectCachePackageShaderIndex[3]; // Index of T3EffectCacheShader
        } *mPassesDraw;
        struct T3EffectCachePassCompute
        {
            uint32_t mThreadGroupSizeX;
            uint32_t mThreadGroupSizeY;
            uint32_t mThreadGroupSizeZ;
            uint32_t t3EffectCachePackageShaderIndex;
        } *mPassesCompute;
    };
};

struct ShaderHeader
{
    uint32_t parameterCount;
    uint32_t shaderSize;
    struct ParameterHeader
    {
        uint16_t parameterIndex;
        uint16_t scalarSize;
        uint8_t location;
        uint8_t samplerLocation;
        uint8_t bindType;
    } *parameters;
};

uint32_t FNV1a(uint32_t hash, const char *input)
{
    while (*input)
    {
        hash = hash * 0x1000193 ^ *input;
        ++input;
    }
    return hash;
}

int T3FXPackRead(FILE *stream)
{
    uint32_t shaderCount = 0;
    struct T3FXPackHeader header;
    fread(&header, sizeof(header), 1, stream);

    struct T3EffectCachePackageShader *shaders = malloc(sizeof(struct T3EffectCachePackageShader) * header.shaderCount);
    fread(shaders, sizeof(struct T3EffectCachePackageShader), header.shaderCount, stream);

    struct T3EffectCacheProgram *programs = malloc(sizeof(struct T3EffectCacheProgram) * header.programCount);
    for (uint32_t i = 0; i < header.programCount; ++i)
    {
        struct T3EffectCacheProgram *currentProgram = programs + i;
        fread(&(programs[i].package), sizeof(programs[i].package) - sizeof(uint32_t), 1, stream);

        programs[i].samplers = malloc(sizeof(struct T3EffectCacheSampler) * programs[i].package.samplerCount);
        fread(programs[i].samplers, sizeof(struct T3EffectCacheSampler), programs[i].package.samplerCount, stream);

        if (categories[programs[i].package.effectType] == eEffectCategory_Compute)
        {
            programs[i].mPassesCompute = malloc(sizeof(struct T3EffectCachePassCompute) * programs[i].package.passCount);
            fread(programs[i].mPassesCompute, sizeof(struct T3EffectCachePassCompute), programs[i].package.passCount, stream);
            ++shaderCount;
        }
        else
        {
            shaderCount += 3;
            programs[i].mPassesDraw = malloc(sizeof(struct T3EffectCachePassDraw) * programs[i].package.passCount);
            fread(programs[i].mPassesDraw, sizeof(struct T3EffectCachePassDraw), programs[i].package.passCount, stream);
        }

        free(programs[i].samplers);
        free(programs[i].mPassesCompute);
    }
    free(shaders);
    free(programs);

    /*
    char buf[1024];
    FILE *shaderFile = cfopen("../plainTexts/ttarchDump/shaders.txt", "wb");
    for (uint32_t i = 0; i < header.cachePackageShaderCount; ++i)
    {
        int length = snprintf(buf, sizeof(buf), "shaderType = %u\n offset = %u\n size = %u\n", shaders[i].shaderType, shaders[i].offset, shaders[i].size);
        fwrite(buf, length, 1, shaderFile);
    }
    */
    return 0;
}